package dev.langchain4j.service.tool.search;
import dev.langchain4j.Internal;import dev.langchain4j.agent.tool.*;import dev.langchain4j.data.message.*;import dev.langchain4j.invocation.InvocationContext;import dev.langchain4j.service.tool.*;import java.util.*;import static dev.langchain4j.internal.Utils.*;import static dev.langchain4j.internal.ValidationUtils.ensureNotNull;
@Internal public class ToolSearchService {private static final String FOUND="found_tools";private final ToolSearchStrategy strategy;public ToolSearchService(ToolSearchStrategy s){strategy=ensureNotNull(s,"toolSearchStrategy");}
 public ToolServiceContext adjust(ToolServiceContext c,List<ChatMessage>messages,InvocationContext i){List<ToolSpecification>search=strategy.getToolSearchTools(i),available=c.availableTools(),effective=effective(search,available,messages),searchable=new ArrayList<ToolSpecification>(available);searchable.removeAll(effective);Map<String,ToolExecutor>extra=new LinkedHashMap<String,ToolExecutor>();for(ToolSpecification t:search)extra.put(t.name(),new SearchExecutor(searchable));return c.toBuilder().effectiveTools(effective).toolExecutors(merge(c.toolExecutors(),extra)).build();}
 private List<ToolSpecification> effective(List<ToolSpecification>s,List<ToolSpecification>a,List<ChatMessage>m){List<ToolSpecification>r=new ArrayList<ToolSpecification>();for(ToolSpecification t:a)if(t.metadata().get(ToolSpecification.METADATA_SEARCH_BEHAVIOR)==SearchBehavior.ALWAYS_VISIBLE)r.add(t);r.addAll(s);if(m==null)return r;Set<String>f=new LinkedHashSet<String>();for(ChatMessage x:m)if(x instanceof ToolExecutionResultMessage){Object v=((ToolExecutionResultMessage)x).attributes().get(FOUND);if(v instanceof List<?>)for(Object n:(List<?>)v)f.add((String)n);}Map<String,ToolSpecification>by=new HashMap<String,ToolSpecification>();for(ToolSpecification t:a)by.put(t.name(),t);for(String n:f){ToolSpecification t=by.get(n);if(t!=null)r.add(t);}return r;}
 public static ToolServiceContext addFoundTools(ToolServiceContext c,Collection<ToolExecutionResult>rs){Set<String>f=new LinkedHashSet<String>();for(ToolExecutionResult r:rs){Object v=r.attributes().get(FOUND);if(v instanceof List<?>)for(Object n:(List<?>)v)f.add((String)n);}if(f.isEmpty())return c;Set<String>e=new HashSet<String>();for(ToolSpecification t:c.effectiveTools())e.add(t.name());Map<String,ToolSpecification>a=new HashMap<String,ToolSpecification>();for(ToolSpecification t:c.availableTools())a.put(t.name(),t);List<ToolSpecification>add=new ArrayList<ToolSpecification>();for(String n:f){if(e.contains(n))continue;ToolSpecification t=a.get(n);if(t==null)throw new IllegalArgumentException("No tool with name '"+n+"' exists");add.add(t);}return add.isEmpty()?c:c.toBuilder().effectiveTools(merge(c.effectiveTools(),add)).build();}
 private final class SearchExecutor implements ToolExecutor{private final List<ToolSpecification>s;private SearchExecutor(List<ToolSpecification>x){s=copy(x);}@Override public ToolExecutionResult executeWithContext(ToolExecutionRequest r,InvocationContext c){ToolSearchResult x=strategy.search(ToolSearchRequest.builder().toolExecutionRequest(r).searchableTools(s).invocationContext(c).build());Map<String,Object>a=new LinkedHashMap<String,Object>();a.put(FOUND,x.foundToolNames());return ToolExecutionResult.builder().result(x).resultText(x.toolResultMessageText()).attributes(a).build();}@Override public String execute(ToolExecutionRequest r,Object m){throw new IllegalStateException("executeWithContext must be called instead");}}
}
